    Bug 2018473 - Fix accumulation of ENVID for DSN-aware servers when sending from Outbox. r=babolivier

    Based on https://github.com/Betterbird/thunderbird-patches/blob/main/140/bugs/2018473-fix-ENVID.patch

    Differential Revision: https://phabricator.services.mozilla.com/D284436

diff --git a/mailnews/compose/src/nsMsgSendLater.cpp b/mailnews/compose/src/nsMsgSendLater.cpp
index 3e8c2665bde..becf3e09cb5 100644
--- a/mailnews/compose/src/nsMsgSendLater.cpp
+++ b/mailnews/compose/src/nsMsgSendLater.cpp
@@ -87,6 +87,7 @@ nsMsgSendLater::~nsMsgSendLater() {
   PR_Free(m_to);
   PR_Free(m_fcc);
   PR_Free(m_bcc);
+  PR_Free(m_messageId);
   PR_Free(m_newsgroups);
   PR_Free(m_headers);
   PR_Free(mLeftoverBuffer);
@@ -875,8 +876,9 @@ nsresult nsMsgSendLater::BuildHeaders() {

   PR_FREEIF(m_to);
   PR_FREEIF(m_bcc);
-  PR_FREEIF(m_newsgroups);
   PR_FREEIF(m_fcc);
+  PR_FREEIF(m_messageId);
+  PR_FREEIF(m_newsgroups);
   PR_FREEIF(mIdentityKey);
   PR_FREEIF(mAccountKey);
   m_flags = 0;
diff --git a/mailnews/compose/test/unit/test_sendMessageLater_dsn_message_id.js b/mailnews/compose/test/unit/test_sendMessageLater_dsn_message_id.js
index ccbc1db8822..e3ea4ef7535 100644
--- a/mailnews/compose/test/unit/test_sendMessageLater_dsn_message_id.js
+++ b/mailnews/compose/test/unit/test_sendMessageLater_dsn_message_id.js
@@ -131,7 +131,8 @@ async function test_dsn_message_id(filename, messageIdPattern) {

   // Test that we sent a message ID that matches with the expected pattern.
   const mailFromLine = server.playTransaction().them[1];
-  const testRegExp = new RegExp(`RET=FULL ENVID=<${messageIdPattern}>`);
+  info(`Mail From line: ${mailFromLine}`);
+  const testRegExp = new RegExp(`RET=FULL ENVID=<${messageIdPattern}>$`);
   Assert.ok(
     testRegExp.test(mailFromLine),
     "smtp client should send a valid message ID"
@@ -158,3 +159,18 @@ add_task(async function test_dsn_message_id_with_header() {
     "f30c39e6-b14b-405a-8bf7-2ccc81fd1f6f@foo.invalid"
   );
 });
+
+/**
+ * Tests that send later for a second message STILL gives just the correct
+ * mail from line (and does not carry forward a doubling of the prev id.)
+ */
+add_task(async function test_dsn_message_id_with_header2() {
+  await test_dsn_message_id(
+    "data/sendlater_dsn_with_message_id.eml",
+    "f30c39e6-b14b-405a-8bf7-2ccc81fd1f6f@foo.invalid"
+  );
+  await test_dsn_message_id(
+    "data/sendlater_dsn_with_message_id.eml",
+    "f30c39e6-b14b-405a-8bf7-2ccc81fd1f6f@foo.invalid"
+  );
+});
